package io.github.diodeme.ji.artifact;

/** Durable ArtifactStore reference identity with its public scoped metadata. */
public record ArtifactReferenceEntry(String referenceId, ArtifactReference reference) {
    public ArtifactReferenceEntry {
        if (referenceId == null || referenceId.isBlank() || reference == null) {
            throw new IllegalArgumentException("Artifact reference entry is incomplete");
        }
    }
}
